// src/components/templates/digital-name-card/obsidian.tsx
// TEMPLATE: Obsidian — High-contrast editorial brutalism, pure black precision
// Research basis: Notion/Linear brutalism + NYT magazine editorial grid

import Image from "next/image";
import type { DigitalNameCardData } from "@/lib/validators/template-schemas";

interface Props { data: DigitalNameCardData; accentColor?: string; }

const PLATFORM_LABELS: Record<string, string> = {
  linkedin: "LinkedIn", github: "GitHub", twitter: "Twitter/X",
  instagram: "Instagram", facebook: "Facebook", youtube: "YouTube",
  tiktok: "TikTok", whatsapp: "WhatsApp", telegram: "Telegram", website: "Website",
};

function contactHref(type: string, value: string) {
  if (type === "email") return `mailto:${value}`;
  if (type === "phone") return `tel:${value.replace(/\s/g, "")}`;
  if (type === "website") return value.startsWith("http") ? value : `https://${value}`;
  return "#";
}

export function ObsidianNameCard({ data, accentColor = "#f59e0b" }: Props) {
  const { fullName, pronouns, jobTitle, company, avatarUrl, bio, tagline,
    contacts, socialLinks, skills, featuredQuote, ctaLabel, ctaUrl } = data;

  return (
    <main className="min-h-screen bg-black px-4 py-12" style={{ fontFamily: "'Space Grotesk', system-ui, sans-serif" }}>
      <div className="mx-auto max-w-sm">

        {/* Accent top rule */}
        <div className="mb-6 h-1 w-12" style={{ background: accentColor }} />

        {/* Identity block */}
        <div className="mb-6 flex items-start gap-4">
          {avatarUrl && (
            <div className="shrink-0 h-20 w-20 overflow-hidden" style={{ outline: `2px solid ${accentColor}` }}>
              <Image src={avatarUrl} alt={fullName} width={80} height={80}
                className="h-full w-full object-cover grayscale contrast-125" priority />
            </div>
          )}
          <div className="flex-1">
            <p className="mb-1 text-xs font-bold uppercase tracking-[0.25em] text-neutral-600">
              {company}
            </p>
            <h1 className="text-3xl font-black leading-none tracking-tighter text-white">
              {fullName}
            </h1>
            {pronouns && <p className="mt-0.5 text-xs text-neutral-600">{pronouns}</p>}
            <p className="mt-1 text-sm font-semibold uppercase tracking-wider" style={{ color: accentColor }}>
              {jobTitle}
            </p>
          </div>
        </div>

        {/* Tagline */}
        {tagline && (
          <p className="mb-5 border-l-2 pl-4 text-sm leading-relaxed text-neutral-400 italic"
            style={{ borderColor: accentColor }}>
            {tagline}
          </p>
        )}

        {/* Bio */}
        {bio && (
          <p className="mb-5 text-sm leading-relaxed text-neutral-400">{bio}</p>
        )}

        {/* Rule */}
        <div className="mb-4 h-px bg-neutral-900" />

        {/* Contact list — full details visible */}
        {contacts.length > 0 && (
          <div className="mb-5 space-y-1">
            <p className="mb-2 text-[10px] font-bold uppercase tracking-[0.25em] text-neutral-700">Contact</p>
            {contacts.map((c, i) => (
              <a key={i} href={contactHref(c.type, c.value)}
                target={c.type === "website" ? "_blank" : undefined}
                rel={c.type === "website" ? "noopener noreferrer" : undefined}
                className="group flex items-baseline justify-between py-2 transition-opacity hover:opacity-70"
                style={{ borderBottom: "1px solid #111" }}>
                <span className="text-xs uppercase tracking-wider text-neutral-700">
                  {c.label ?? c.type}
                </span>
                <span className="text-right text-sm text-white">{c.value}</span>
              </a>
            ))}
          </div>
        )}

        {/* Social — horizontal labels */}
        {socialLinks.length > 0 && (
          <div className="mb-5">
            <p className="mb-2 text-[10px] font-bold uppercase tracking-[0.25em] text-neutral-700">Social</p>
            <div className="flex flex-wrap gap-1.5">
              {socialLinks.map((s, i) => (
                <a key={i} href={s.url} target="_blank" rel="noopener noreferrer"
                  className="border px-3 py-1.5 text-xs font-medium text-neutral-400 transition-all hover:border-neutral-500 hover:text-white"
                  style={{ borderColor: "#222" }}>
                  {s.label ?? PLATFORM_LABELS[s.platform] ?? s.platform}
                </a>
              ))}
            </div>
          </div>
        )}

        {/* Skills — tag grid */}
        {skills && skills.length > 0 && (
          <div className="mb-5">
            <p className="mb-2 text-[10px] font-bold uppercase tracking-[0.25em] text-neutral-700">Expertise</p>
            <div className="flex flex-wrap gap-1.5">
              {skills.map((s, i) => (
                <span key={i} className="bg-neutral-950 border border-neutral-800 px-2.5 py-1 text-xs text-neutral-400">
                  {s.name}
                  {s.level !== undefined && (
                    <span className="ml-1.5 font-bold text-white">{s.level}%</span>
                  )}
                </span>
              ))}
            </div>
          </div>
        )}

        {/* Quote */}
        {featuredQuote && (
          <div className="mb-5">
            <p className="text-xl font-black leading-tight text-white" style={{ fontStyle: "italic" }}>
              &ldquo;{featuredQuote}&rdquo;
            </p>
          </div>
        )}

        {/* Rule */}
        <div className="mb-4 h-px bg-neutral-900" />

        {/* CTA */}
        {ctaLabel && ctaUrl && (
          <a href={ctaUrl} target="_blank" rel="noopener noreferrer"
            className="flex w-full items-center justify-between px-5 py-4 text-sm font-black uppercase tracking-wider text-black transition-opacity hover:opacity-80"
            style={{ background: accentColor }}>
            <span>{ctaLabel}</span>
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor"
              strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
              <path d="M7 17L17 7M7 7h10v10" />
            </svg>
          </a>
        )}

        <p className="mt-6 text-center text-[10px] uppercase tracking-[0.3em] text-neutral-900">PresenceCard</p>
      </div>
    </main>
  );
}
